from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
rows=json.loads((R/'results/results.json').read_text())['retention']
data=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Возврат к занятиям после ошибки</title><style>
:root{color-scheme:light;--ink:#172b3a;--muted:#536878;--accent:#087d7a;--other:#9aadb4;--surface:#f2f6f6}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,sans-serif;background:#fff;color:var(--ink)}main{max-width:1100px;margin:auto;padding:48px 24px}h1{font-size:clamp(28px,4vw,43px);letter-spacing:-.035em;margin:0 0 12px}p{line-height:1.55;max-width:75ch;color:var(--muted)}.top{padding-bottom:24px;border-bottom:1px solid #dbe5e5}.controls{display:flex;gap:18px;flex-wrap:wrap;padding:22px 0 4px}.controls label{display:grid;gap:7px;font-size:14px;font-weight:650}select{font:inherit;padding:9px 12px;border:1px solid #bbcdd0;border-radius:6px;background:white;color:var(--ink)}select:focus-visible{outline:3px solid #60b9b2}.layout{display:grid;grid-template-columns:1fr 1fr;gap:32px;margin-top:26px}section{padding:20px;background:var(--surface);border-radius:8px}h2{font-size:20px;margin:0 0 5px}small{color:var(--muted)}.barrow{margin-top:26px}.label{display:flex;justify-content:space-between;gap:10px;align-items:baseline;flex-wrap:wrap}.name{font-weight:650}.value{font-size:21px;font-weight:750}.track{height:17px;background:#dbe6e6;border-radius:3px;margin:10px 0 7px}.bar{height:100%;background:var(--accent);border-radius:3px}.other{background:var(--other)}.description{font-size:14px}.foot{padding-top:26px;font-size:14px}a{color:#006c6b}@media(max-width:700px){main{padding:30px 18px}.layout{grid-template-columns:1fr}}
</style></head><body><main><header class="top"><h1>Возврат после ошибки</h1><p>Первая обнаруженная ошибка в первом наблюдаемом сеансе, режим diagnosis. Учебный анализ EdNet KT3; показатели зависят от выбранных условий расчёта.</p></header><div class="controls"><label>Граница сеанса<select id="gap"><option value="15">15 минут</option><option value="30" selected>30 минут</option><option value="60">60 минут</option></select></label><label>Условный конец наблюдения<select id="boundary"><option value="0">Последнее событие выборки</option><option value="30">На 30 дней раньше</option><option value="60">На 60 дней раньше</option></select></label></div><div class="layout"><section><h2>Возврат D1</h2><small>Новый сеанс через 24–48 часов после окончания первого</small><div id="d1"></div></section><section><h2>Возврат D7</h2><small>Новый сеанс через 168–192 часа после окончания первого</small><div id="d7"></div></section></div><div class="foot"><p>Продолжение — открытие следующего блока в том же сеансе. Для расчёта включены пользователи, чьё окно полностью укладывается в условную границу. Максимальная дата — приближение; общий сдвиг времени не подтверждён.</p><p>В меньшей группе D7 очень мало возвратов. Различие показывает связь и не доказывает, что продолжение занятия стало причиной возврата. Данные — <a href="https://github.com/riiid/ednet">EdNet</a>.</p></div></main><script>
const data=__DATA__;const fmt=n=>new Intl.NumberFormat('ru-RU').format(n);function render(){const gap=+document.querySelector('#gap').value,boundary=+document.querySelector('#boundary').value;for(const metric of ['D1','D7']){const target=document.querySelector('#'+metric.toLowerCase());const selected=data.filter(x=>x.session_gap_min===gap&&x.boundary_offset_days===boundary&&x.metric===metric).sort((a,b)=>Number(b.continued)-Number(a.continued));target.replaceChildren();for(const x of selected){const row=document.createElement('div');row.className='barrow';const label=document.createElement('div');label.className='label';const name=document.createElement('span');name.className='name';name.textContent=x.continued?'Начали следующий блок':'Не начали следующий блок';const val=document.createElement('span');val.className='value';val.textContent=x.percent.toFixed(2).replace('.',',')+'%';label.append(name,val);const track=document.createElement('div');track.className='track';const bar=document.createElement('div');bar.className=x.continued?'bar':'bar other';bar.style.width=Math.min(x.percent/15*100,100)+'%';track.append(bar);const desc=document.createElement('div');desc.className='description';desc.textContent=fmt(x.returned)+' вернулись из '+fmt(x.users)+' пользователей';row.append(label,track,desc);target.append(row)}}}document.querySelectorAll('select').forEach(x=>x.addEventListener('change',render));render();</script></body></html>'''.replace('__DATA__',data)
(R/'results/dashboard.html').write_text(html,encoding='utf8')
print('Готово: results/dashboard.html')
